#pragma once
#include <fstream>
#include "modules/audio_processing/aec3/darling_diagnostics.h"
// Raw normalized float32, 48 kHz mono; generated by compare-aec.mjs.
inline int CompareAec(int argc, char** argv) {
  if(argc!=7 && argc!=8 && argc!=10) return 2;
  const bool trace=argc==8 && std::string(argv[7])=="--trace-linear";
  const bool internals=argc==10 && std::string(argv[7])=="--trace-internals";
  if(argc==8 && !trace) return 2;
  if(argc==10 && !internals) return 2;
  const int trace_start=internals?std::atoi(argv[8]):-1;
  const int trace_end=internals?std::atoi(argv[9]):-1;
  if(internals && (trace_start<0 || trace_end<=trace_start)) return 2;
  const std::string algorithm=argv[2];
  const bool candidate=algorithm=="aec3-nearend-mask";
  const bool bounded=algorithm=="aec3-bounded-residual";
  const bool sensitive=algorithm=="aec3-sensitive" || algorithm=="aec3-sensitive-mask";
  const bool sensitive_mask=algorithm=="aec3-sensitive-mask";
  const bool official=algorithm=="aec3" || candidate || bounded || sensitive;
  if(!official && algorithm!="pbfdaf") return 2;
  if((trace || internals) && !official) return 2;
  const bool noise=std::string(argv[3])=="1";
  std::ifstream reference(argv[4],std::ios::binary), capture(argv[5],std::ios::binary);
  std::ofstream output(argv[6],std::ios::binary|std::ios::trunc);
  if(!reference || !capture || !output) return 3;
  webrtc::AudioProcessing::Config config;
  config.echo_canceller.enabled=official;
  config.echo_canceller.export_linear_aec_output=trace;
  config.echo_canceller.mobile_mode=false;
  config.echo_canceller.enforce_high_pass_filtering=false;
  config.high_pass_filter.enabled=false;
  config.noise_suppression.enabled=false;
  config.gain_controller1.enabled=false; config.gain_controller2.enabled=false;
  webrtc::BuiltinAudioProcessingBuilder builder(config);
  if(candidate || bounded || sensitive || trace) {
    // Offline-only hypothesis: relax masking AFTER near-end dominance is
    // detected. Do not change detection thresholds or the linear canceller.
    webrtc::EchoCanceller3Config tuning;
    if(candidate || sensitive_mask) tuning.suppressor.nearend_tuning.mask_hf={3.f,4.f,.3f};
    if(bounded) tuning.suppressor.dominant_nearend_detection.use_unbounded_echo_spectrum=false;
    if(sensitive) {
      // Diagnostic only: require less nearend/echo dominance, lower the
      // nearend/noise requirement, react sooner and hold protection longer.
      tuning.suppressor.dominant_nearend_detection.enr_threshold=.75f;
      tuning.suppressor.dominant_nearend_detection.snr_threshold=10.f;
      tuning.suppressor.dominant_nearend_detection.trigger_threshold=6;
      tuning.suppressor.dominant_nearend_detection.hold_duration=100;
    }
    tuning.filter.export_linear_aec_output=trace;
    builder.SetEchoCancellerConfig(tuning,std::nullopt);
  }
  auto ns=noise?std::make_shared<RnnoiseMetrics>():nullptr;
  auto a=std::make_shared<darling::AecMetrics>();
  auto b=std::make_shared<darling::Aec3PipelineMetrics>();
  if(official) builder.SetCapturePostProcessing(std::make_unique<darling::Aec3PostProcessing>(b,ns));
  else {
    auto queue=std::make_shared<darling::RenderReferenceQueue>();
    builder.SetRenderPreProcessing(std::make_unique<darling::RenderReferenceTap>(queue));
    builder.SetCapturePostProcessing(std::make_unique<darling::CaptureChain>(queue,noise,a,ns));
  }
  auto apm=builder.Build(webrtc::CreateEnvironment());
  webrtc::darling_aec3_diagnostics::Reset();
  webrtc::darling_aec3_diagnostics::Enable(false);
  const webrtc::StreamConfig format(48000,1);
  std::array<float,480> r{},c{},o{},ro{};
  std::ofstream linear,final_low;
  webrtc::AudioBuffer split(48000,1,48000,1,48000,1);
  if(trace) {
    linear.open(std::string(argv[6])+".linear16.f32",std::ios::binary);
    final_low.open(std::string(argv[6])+".final16.f32",std::ios::binary);
    if(!linear || !final_low) return 9;
  }
  std::vector<double> times;
  int frame_index=0;
  while(reference.read(reinterpret_cast<char*>(r.data()),1920)) {
    if(!capture.read(reinterpret_cast<char*>(c.data()),1920)) return 4;
    for(size_t i=0;i<480;++i) if(!std::isfinite(r[i]) || !std::isfinite(c[i]) || std::abs(r[i])>1 || std::abs(c[i])>1) return 5;
    const float* rp[]={r.data()}; const float* cp[]={c.data()};
    float* op[]={o.data()}; float* rout[]={ro.data()};
    const auto start=std::chrono::steady_clock::now();
    if(internals) webrtc::darling_aec3_diagnostics::Enable(frame_index>=trace_start && frame_index<trace_end);
    if(apm->ProcessReverseStream(rp,format,format,rout) || apm->ProcessStream(cp,format,format,op)) return 6;
    times.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-start).count());
    ++frame_index;
    for(float v:o) if(!std::isfinite(v) || std::abs(v)>1) return 7;
    output.write(reinterpret_cast<const char*>(o.data()),1920);
    if(trace) {
      std::array<std::array<float,160>,1> low{};
      if(!apm->GetLinearAecOutput(low)) return 10;
      linear.write(reinterpret_cast<const char*>(low[0].data()),640);
      for(size_t i=0;i<480;++i) split.channels()[0][i]=o[i]*32768.f;
      split.SplitIntoFrequencyBands();
      for(size_t i=0;i<160;++i) low[0][i]=split.split_bands_const(0)[0][i]/32768.f;
      final_low.write(reinterpret_cast<const char*>(low[0].data()),640);
    }
  }
  if(reference.gcount() || capture.peek()!=std::char_traits<char>::eof() || times.empty() || !output || (trace && (!linear || !final_low))) return 8;
  std::sort(times.begin(),times.end());
  const auto& d=webrtc::darling_aec3_diagnostics::stats;
  std::printf("{\"frames\":%zu,\"p95Us\":%.2f,\"protection\":%llu",times.size(),times[times.size()*95/100],
      static_cast<unsigned long long>(official?b->output_protection.load():a->output_protection.load()));
  if(internals) std::printf(",\"dominantFraction\":%.6f,\"usableLinearFraction\":%.6f,\"residualNearendRatio\":%.6f,\"unboundedNearendRatio\":%.6f,\"meanGain\":%.6f,\"gainP10\":%.2f,\"gainP50\":%.2f,\"gainP90\":%.2f,\"dominantMeanGain\":%.6f,\"normalMeanGain\":%.6f",
      double(d.dominant)/d.blocks,double(d.usable_linear)/d.blocks,d.residual_power_sum/std::max(d.nearend_power_sum,1e-20),
      d.unbounded_power_sum/std::max(d.nearend_power_sum,1e-20),d.gain_sum/d.blocks,webrtc::darling_aec3_diagnostics::GainPercentile(.1),
      webrtc::darling_aec3_diagnostics::GainPercentile(.5),webrtc::darling_aec3_diagnostics::GainPercentile(.9),
      d.dominant_gain_sum/std::max<uint64_t>(d.dominant_gain_count,1),d.normal_gain_sum/std::max<uint64_t>(d.normal_gain_count,1));
  std::printf("}\n");
  webrtc::darling_aec3_diagnostics::Enable(false);
  return 0;
}
